import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec4, mix, smoothstep, time, uniform, attribute } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, Vector3 } = THREE;

  const group = new Group();
  group.userData.handlers = {};
  group.userData.cleanup = () => {
    gsap.killTweensOf(tileObjects);
    tileObjects.forEach(tile => {
      tile.geometry.dispose();
      tile.material.dispose();
    });
  };

  // Parse text content with fallback
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const brandMarks = ['HODINKEE', 'MONOCLE', 'WALLPAPER', 'ESQUIRE', 'WIRED', 'FINANCIAL TIMES'];
  const kickerText = 'AS FEATURED IN';

  // Render kicker text
  const kicker = ctx.fontAtlas.createText(kickerText, {
    fontSize: 9,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 1.08
  });
  kicker.position.set(0, 0.9, 0);
  group.add(kicker);

  // Grid layout: 3x2, gap 0.25, tile size 1.0w x 0.62h
  const tileWidth = 1.0;
  const tileHeight = 0.62;
  const gap = 0.25;
  const gridWidth = 3 * tileWidth + 2 * gap;
  const gridHeight = 2 * tileHeight + gap;
  const startX = -gridWidth / 2;
  const startY = gridHeight / 2;

  const tileObjects = [];
  const tileGeometry = new PlaneGeometry(tileWidth, tileHeight, 4, 4);
  const tileGeometryBeveled = new PlaneGeometry(tileWidth - 0.04, tileHeight - 0.04, 4, 4);

  // Create vertex positions for chamfered edges
  const positions = tileGeometryBeveled.attributes.position;
  const posArray = positions.array;
  const chamferRadius = 0.02;

  for (let i = 0; i < posArray.length; i += 3) {
    const x = posArray[i];
    const y = posArray[i + 1];
    const halfW = (tileWidth - 0.04) / 2;
    const halfH = (tileHeight - 0.04) / 2;

    // Chamfer corners
    if (Math.abs(x) > halfW - chamferRadius && Math.abs(y) > halfH - chamferRadius) {
      const cornerX = Math.sign(x) * (halfW - chamferRadius);
      const cornerY = Math.sign(y) * (halfH - chamferRadius);
      const distX = Math.abs(x) - Math.abs(cornerX);
      const distY = Math.abs(y) - Math.abs(cornerY);
      const dist = Math.sqrt(distX * distX + distY * distY);
      if (dist < chamferRadius) {
        const factor = 1 - (chamferRadius - dist) / chamferRadius * 0.5;
        posArray[i] *= factor;
        posArray[i + 1] *= factor;
      }
    }
  }
  positions.needsUpdate = true;

  // Material with brushed anisotropic finish and vertical gradient
  const createTileMaterial = () => {
    const gradientStops = [
      { at: 0, hex: '#1a1a22' },
      { at: 1, hex: '#121218' }
    ];

    const uvNode = uv();
    const gradientColor = mix(
      vec3(0.102, 0.102, 0.133),
      vec3(0.071, 0.071, 0.098),
      smoothstep(0.0, 1.0, uvNode.y)
    );

    const material = new MeshStandardNodeMaterial({
      colorNode: gradientColor,
      roughnessNode: uniform(0.55),
      metalnessNode: uniform(0.5),
      clearcoatNode: uniform(0.2),
      normalScale: new Vector3(1.0, 1.0, 1.0)
    });

    // Anisotropy simulation via roughness variation
    material.anisotropyStrength = 0.6;
    material.anisotropyRotation = 0;

    return material;
  };

  const tilePositions = [];
  for (let row = 0; row < 2; row++) {
    for (let col = 0; col < 3; col++) {
      tilePositions.push({
        x: startX + col * (tileWidth + gap) + tileWidth / 2,
        y: startY - row * (tileHeight + gap) - tileHeight / 2,
        index: row * 3 + col
      });
    }
  }

  tilePositions.forEach(pos => {
    const tile = new Mesh(tileGeometryBeveled, createTileMaterial());
    tile.position.set(pos.x, pos.y, 0);
    tile.userData.originalZ = 0;
    tile.userData.hoverActive = false;

    // Render brand mark text on tile
    const markText = ctx.fontAtlas.createText(brandMarks[pos.index], {
      fontSize: 13,
      color: '#e8ecf2',
      align: 'center'
    });
    markText.position.z = 0.01;
    markText.material.opacity = 0.78;
    markText.material.transparent = true;
    tile.add(markText);
    tile.userData.markText = markText;

    // Hover interaction
    group.userData.handlers[`tile-${pos.index}`] = {
      hover: (state) => {
        tile.userData.hoverActive = state;
        gsap.to(tile.position, {
          z: state ? 0.05 : 0,
          duration: 0.16,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
        });
        gsap.to(markText.material, {
          opacity: state ? 1.0 : 0.78,
          duration: 0.16,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
        });
      }
    };

    // Enable hover detection
    tile.userData.isHoverable = true;

    group.add(tile);
    tileObjects.push(tile);
  });

  // Stagger entrance animation: fade-up with y offset
  const staggerDelay = 0.08;
  tileObjects.forEach((tile, idx) => {
    const isTopRow = idx < 3;
    const colIndex = isTopRow ? idx : idx - 3;
    const staggerIndex = isTopRow ? colIndex : 3 + colIndex;

    tile.position.y += 0.2;
    tile.material.transparent = true;
    tile.material.opacity = 0;
    tile.userData.markText.material.opacity = 0;

    gsap.to(tile.position, {
      y: tilePositions[staggerIndex].y,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      delay: staggerIndex * staggerDelay
    });

    gsap.to(tile.material, {
      opacity: 1,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      delay: staggerIndex * staggerDelay
    });

    gsap.to(tile.userData.markText.material, {
      opacity: 0.78,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      delay: staggerIndex * staggerDelay
    });
  });

  // Add key light to rake across tiles at 35 deg elevation
  const keyLight = new THREE.DirectionalLight(0xffffff, 1.2);
  const elevation = (35 * Math.PI) / 180;
  const azimuth = (0 * Math.PI) / 180;
  keyLight.position.set(
    Math.cos(azimuth) * Math.cos(elevation),
    Math.sin(elevation),
    Math.sin(azimuth) * Math.cos(elevation)
  );
  keyLight.position.normalize().multiplyScalar(3);
  group.add(keyLight);

  // Rim light opposite
  const rimLight = new THREE.DirectionalLight(0xe8ecf2, 0.6);
  rimLight.position.set(-2, 1.5, 2);
  group.add(rimLight);

  // Ambient fill
  const ambientLight = new THREE.AmbientLight(0xffffff, 0.4);
  group.add(ambientLight);

  return group;
}
